CREATE TABLE IF NOT EXISTS deals(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,brand TEXT,store TEXT NOT NULL,category TEXT NOT NULL,image_url TEXT,product_url TEXT NOT NULL,original_price NUMERIC(12,2) NOT NULL,current_price NUMERIC(12,2) NOT NULL,previous_price NUMERIC(12,2),coupon_code TEXT,coupon_min_order NUMERIC(12,2),coupon_type TEXT,expiry_at TIMESTAMPTZ,last_checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),verified BOOLEAN NOT NULL DEFAULT FALSE,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE TABLE IF NOT EXISTS price_history(id BIGSERIAL PRIMARY KEY,deal_id BIGINT REFERENCES deals(id) ON DELETE CASCADE,price NUMERIC(12,2) NOT NULL,checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE TABLE IF NOT EXISTS notification_logs(id BIGSERIAL PRIMARY KEY,deal_id BIGINT REFERENCES deals(id) ON DELETE SET NULL,channel TEXT NOT NULL,event_type TEXT NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE INDEX IF NOT EXISTS deals_public_idx ON deals(enabled,verified);CREATE INDEX IF NOT EXISTS deals_store_idx ON deals(store);CREATE INDEX IF NOT EXISTS deals_category_idx ON deals(category);